// One sheet row per transcript. Error rows (no captions, private, age-restricted, not found) are free and skipped.
// A Google Sheets cell holds at most 50,000 characters, so very long transcripts are cut and flagged.
const MAX_CHARS = 49000;
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.rowType !== 'transcript') continue;
  const text = r.transcript ?? '';
  out.push({
    json: {
      videoId: r.videoId,
      title: r.title ?? '',
      channel: r.channelName ?? '',
      publishDate: (r.publishDate ?? '').slice(0, 10),
      durationSeconds: r.durationSeconds ?? '',
      language: r.language ?? '',
      autoCaptions: r.isAutoGenerated === true,
      wordCount: r.wordCount ?? '',
      url: r.url,
      transcript: text.slice(0, MAX_CHARS),
      truncated: text.length > MAX_CHARS,
      summary: '',
      scrapedAt: r.scrapedAt,
    },
  });
}
return out;
